def make_pay(kind):
    table = {"card": card, "paypal": paypal}
    return table[kind]

pay = make_pay("paypal")
print(pay(50))

class Order:
    def __init__(self):
        self.subs = []

    def subscribe(self, fn):
        self.subs.append(fn)

    def place(self):
        for fn in self.subs:
            fn(self)
